INSERT INTO inventory (prod_id, client_id, ware_id, quantity)
SELECT i.prod_id, i.client_id, i.ware_id, i.quantity
FROM inbound i
WHERE (i.prod_id, i.client_id) IN

    #{pair.prodId}, #{pair.clientId}
;
